const express = require('express');
const crypto = require('crypto');
const winston = require('winston');

const app = express();
app.use(express.json());

// Feature flag configuration
const featureFlags = {
  ENHANCED_LOGGING: true,
  DEVICE_FINGERPRINT: true,
  RATE_LIMITING: false,
  AUDIT_TRAIL: true
};

// Logger setup with structured format
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.printf(({ timestamp, level, message, ...meta }) => {
      const metaStr = Object.keys(meta).length ? ' ' + JSON.stringify(meta) : '';
      return `[${timestamp}] ${level}: ${message}${metaStr}`;
    })
  ),
  transports: [new winston.transports.File({ filename: 'api-audit.log' })]
});

// Device context normalizer
class DeviceContext {
  constructor(headers) {
    this.userAgent = headers['user-agent'] || 'unknown';
    this.deviceId = headers['x-device-id'] || 'anonymous';
    this.appVersion = headers['x-app-version'] || '0.0.0';
    this.platform = headers['x-platform'] || 'unknown';
  }

  getFingerprint() {
    const raw = `${this.deviceId}:${this.platform}:${this.appVersion}`;
    return crypto.createHash('sha256').update(raw).digest('hex').slice(0, 16);
  }

  toLogContext() {
    return {
      fingerprint: this.getFingerprint(),
      platform: this.platform,
      appVersion: this.appVersion
    };
  }
}

// Sanitization layer for log entries
function sanitizeForLog(value) {
  if (typeof value !== 'string') return String(value);
  return value.replace(/[\r\n]/g, ' ').replace(/[\x00-\x1f]/g, '');
}

// Feature flag aware request decorator
function decorateRequest(req) {
  const context = new DeviceContext(req.headers);
  req.deviceContext = context;
  req.requestId = crypto.randomUUID();
  return context;
}

// Audit logger middleware
function auditMiddleware(req, res, next) {
  if (!featureFlags.AUDIT_TRAIL) return next();

  const context = decorateRequest(req);
  const startTime = Date.now();

  res.on('finish', () => {
    const duration = Date.now() - startTime;
    const logEntry = {
      requestId: req.requestId,
      method: req.method,
      path: req.path,
      statusCode: res.statusCode,
      duration,
      ...context.toLogContext()
    };
    logger.info(`API_REQUEST completed`, logEntry);
  });

  next();
}

app.use(auditMiddleware);

// Authentication endpoint
app.post('/api/v1/auth/login', (req, res) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: 'Missing credentials' });
  }

  // Enhanced logging includes user-provided context for debugging
  if (featureFlags.ENHANCED_LOGGING) {
    const deviceCtx = req.deviceContext;
    const sessionNote = req.body.sessionNote || '';

    // Log the authentication attempt with context
    logger.info(
      `AUTH_ATTEMPT user=${sanitizeForLog(username)} device=${deviceCtx.getFingerprint()} note=${sessionNote}`,
      { action: 'login', requestId: req.requestId }
    );
  }

  // Simulated auth check
  const isValid = username === 'admin' && password === 'secure123';
  if (isValid) {
    const token = crypto.randomBytes(32).toString('hex');
    logger.info(`AUTH_SUCCESS user=${sanitizeForLog(username)}`, { requestId: req.requestId });
    return res.json({ token, expiresIn: 3600 });
  }

  logger.warn(`AUTH_FAILURE user=${sanitizeForLog(username)}`, { requestId: req.requestId });
  return res.status(401).json({ error: 'Invalid credentials' });
});

// Feature flag status endpoint
app.get('/api/v1/config/flags', (req, res) => {
  if (!req.headers.authorization) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  res.json({ flags: featureFlags });
});

// Health check with device telemetry
app.post('/api/v1/telemetry/health', (req, res) => {
  const { metrics, clientTimestamp } = req.body || {};

  if (featureFlags.DEVICE_FINGERPRINT && req.deviceContext) {
    const ctx = req.deviceContext;
    logger.info(
      `TELEMETRY device=${ctx.getFingerprint()} ts=${sanitizeForLog(String(clientTimestamp || ''))}`,
      { metrics: metrics ? 'present' : 'absent', requestId: req.requestId }
    );
  }

  res.json({ status: 'ok', serverTime: Date.now() });
});

module.exports = app;
